		validator.validate( command );

            entity.setActuatorInstanceId( command.getActuatorInstanceId() );
            entity.setName( command.getName() );
            entity.setCommandTopic( command.getCommandTopic() );
            entity.setDevice( command.getDevice() );
            entity.setSupportedCommands( command.getSupportedCommands() );
            entity.setActuatorType( command.getActuatorType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ActuatorInstance {0} ", entity.toString() );

